package com.algoprep.aireview.application.dto;

import com.algoprep.aireview.domain.model.FeatureCode;
import java.util.Objects;
import java.util.UUID;

/**
 * One finished LLM call. {@code callId} is generated by the caller before the call and is the
 * ledger idempotency key. Token counts are {@code Integer}: null means the provider reported no
 * usage, which writes no row (BR-AI-01). {@code problemId} is required by the table check for
 * SOLUTION_REVIEW and GENERATE_TESTCASE and must be null for the other two features.
 */
public record RecordAiTokenUsageCommand(
    UUID callId,
    UUID userId,
    FeatureCode featureCode,
    UUID problemId,
    UUID ownerId,
    Integer tokensPrompt,
    Integer tokensCompletion,
    String modelName) {
  public RecordAiTokenUsageCommand {
    Objects.requireNonNull(callId, "callId");
    Objects.requireNonNull(userId, "userId");
    Objects.requireNonNull(featureCode, "featureCode");
    Objects.requireNonNull(ownerId, "ownerId");
    Objects.requireNonNull(modelName, "modelName");
    if ((tokensPrompt != null && tokensPrompt < 0)
        || (tokensCompletion != null && tokensCompletion < 0)) {
      throw new IllegalArgumentException("token counts must not be negative");
    }
  }

  public boolean usageKnown() {
    return tokensPrompt != null && tokensCompletion != null;
  }
}
